import numpy as np

def wls(X, y, w):
    W = np.diag(w)
    return np.linalg.solve(X.T @ W @ X, X.T @ W @ y)

def lwr_predict(xq, x, y, tau):
    X = np.c_[np.ones_like(x), x]            # 절편 포함
    w = np.exp(-(x - xq) ** 2 / (2 * tau ** 2))
    theta = wls(X, y, w)
    return theta @ np.array([1.0, xq])

rng = np.random.default_rng(0)
x = np.linspace(0, 6, 60)
y = np.sin(x) + rng.normal(0, 0.2, x.size)   # 곡선 데이터

for tau in (0.03, 0.1, 0.5, 5.0):
    pred = np.array([lwr_predict(q, x, y, tau) for q in x])
    print(tau, np.mean((pred - np.sin(x)) ** 2).round(4))
# τ=5 는 직선에 가까워 곡선을 놓치고(오차 ≈0.18), 너무 작은 τ 는 잡음을 따라간다.
